cd /tmp && cat > overflow.py <<'PY'
from playwright.sync_api import sync_playwright
import pathlib
base = pathlib.Path("/Users/miykael/Documents/self/个人资料/en-app/prototype")
pages = ["ask","compare","home","onboarding","audio-only","settings","learn",
         "word-learn","review","sentences","profile","states"]
with sync_playwright() as p:
    b = p.chromium.launch(channel="chrome")
    bad = []
    for name in pages:
        pg = b.new_page(viewport={"width":460,"height":960})
        pg.goto((base/f"pages/{name}.html").as_uri())
        pg.wait_for_timeout(200)
        # 检查横向溢出与被挤扁的元素
        r = pg.evaluate("""() => {
          const out = [];
          const phone = document.querySelector('.phone');
          if (phone && phone.scrollWidth > phone.clientWidth + 1) out.push('横向溢出 '+phone.scrollWidth+'>'+phone.clientWidth);
          document.querySelectorAll('.screen-body:not([hidden]) > *').forEach(el => {
            if (el.offsetParent === null) return;
            if (el.scrollHeight > el.clientHeight + 2 && getComputedStyle(el).overflowY !== 'auto')
              out.push('被压缩: ' + (el.className||el.tagName) + ' ' + el.clientHeight + '<' + el.scrollHeight);
          });
          return out;
        }""")
        if r: bad.append((name, r))
        pg.close()
    b.close()
print("布局问题:", bad if bad else "无")
PY
